mapper.select:
/* isry.cysns.stats.mediaaImprnmMng.mapper.MediaaImprnmMngMapper.selectMediaaImprnmMngList - Lee Hye Sun */ SELECT NVL(CTPV, '합계') AS CTPV , MAX(CTPV_CD) AS CTPV_CD , SUM(NVL(IMPRVM_1, 0)) AS IMPRVM_1 , SUM(NVL(IMPRVM_2,0)) AS IMPRVM_2 , SUM(NVL(IMPRVM_3,0)) AS IMPRVM_3 , SUM(NVL(KEEP_1,0)) AS KEEP_1 , SUM(NVL(KEEP_2,0)) AS KEEP_2 , SUM(NVL(KEEP_3,0)) AS KEEP_3 , SUM(NVL(UNIMPRVM_1,0)) AS UNIMPRVM_1 , SUM(NVL(UNIMPRVM_2,0)) AS UNIMPRVM_2 , SUM(NVL(UNIMPRVM_3,0)) AS UNIMPRVM_3 , SUM(NVL(UNIPT,0)) AS UNIPT , SUM(NVL(INGRAS,0)) AS INGRAS , SUM(NVL(DGNSS_SUM,0)) AS DGNSS_SUM FROM ( SELECT A.ADDTNG_MNG_VALUE1 AS CTPV , A.CMMNS_CD_VALUE AS CTPV_CD , B.IMPRVM_1 , B.IMPRVM_2 , B.IMPRVM_3 , B.KEEP_1 , B.KEEP_2 , B.KEEP_3 , B.UNIMPRVM_1 , B.UNIMPRVM_2 , B.UNIMPRVM_3 , B.UNIPT , B.INGRAS , SUM(B.IMPRVM_1 + B.IMPRVM_2 + B.IMPRVM_3 + B.KEEP_1 + B.KEEP_2 + B.KEEP_3 + B.UNIMPRVM_1 + B.UNIMPRVM_2 + B.UNIMPRVM_3 + B.UNIPT + B.INGRAS) AS DGNSS_SUM FROM ( --통계틀 SELECT CMMNS_CD_VALUE , ADDTNG_MNG_VALUE1 FROM SAC100 WHERE CMMNS_CD_ID = 'CTPV_SE_CD' ) A LEFT JOIN( SELECT D.CTPV_CD
, COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '1' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '3' THEN 1 END) AS IMPRVM_1 --위험-일반 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '1' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '2' THEN 1 END) AS IMPRVM_2 --위험-주의 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '2' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '3' THEN 1 END) AS IMPRVM_3 --주의-일반 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '1' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '1' THEN 1 END) AS KEEP_1 --위험-위험 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '2' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '2' THEN 1 END) AS KEEP_2 --주의-주의 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '3' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '3' THEN 1 END) AS KEEP_3 --일반-일반 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '3' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '2' THEN 1 END) AS UNIMPRVM_1 --일반-주의 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '2' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '1' THEN 1 END) AS UNIMPRVM_2 --주의-위험 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD = '3' AND A.AFTFCT_INTNET_DGNSS_SE_CD = '1' THEN 1 END) AS UNIMPRVM_3 --일반-위험 , COUNT(CASE WHEN A.BEFFAT_INTNET_DGNSS_SE_CD IS NULL OR A.AFTFCT_INTNET_DGNSS_SE_CD IS NULL THEN 1 END) AS UNIPT , COUNT(CASE WHEN A.AFTFCT_INTNET_DGNSS_SE_CD = '9' THEN 1 END) AS INGRAS
, COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '1' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '3' THEN 1 END) AS IMPRVM_1 --위험-일반 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '1' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '2' THEN 1 END) AS IMPRVM_2 --위험-주의 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '2' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '3' THEN 1 END) AS IMPRVM_3 --주의-일반 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '1' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '1' THEN 1 END) AS KEEP_1 --위험-위험 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '2' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '2' THEN 1 END) AS KEEP_2 --주의-주의 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '3' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '3' THEN 1 END) AS KEEP_3 --일반-일반 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '3' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '2' THEN 1 END) AS UNIMPRVM_1 --일반-주의 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '2' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '1' THEN 1 END) AS UNIMPRVM_2 --주의-위험 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD = '3' AND A.AFTFCT_SMRTP_DGNSS_SE_CD = '1' THEN 1 END) AS UNIMPRVM_3 --일반-위험 , COUNT(CASE WHEN A.BEFFAT_SMRTP_DGNSS_SE_CD IS NULL OR A.AFTFCT_SMRTP_DGNSS_SE_CD IS NULL THEN 1 END) AS UNIPT , COUNT(CASE WHEN A.AFTFCT_SMRTP_DGNSS_SE_CD = '9' THEN 1 END) AS INGRAS
FROM ACA200 A JOIN SEB100 B ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEB150 C ON B.CASE_MNG_NO = C.CASE_MNG_NO AND B.CASE_MNG_ODRNO = C.CASE_MNG_ODRNO AND PCHPRS_YN = 'Y' LEFT JOIN SAA000 D ON D.INST_NO = C.PIC_INST_NO
WHERE 1=1
AND D.SGG_CD = #{SGG_CD}
AND D.CTPV_CD = #{CTPV_CD}
AND D.INST_NO = #{INST_NO}
GROUP BY D.CTPV_CD, D.SGG_CD ) B ON A.CMMNS_CD_VALUE = B.CTPV_CD
GROUP BY A.CMMNS_CD_VALUE, A.ADDTNG_MNG_VALUE1 , B.IMPRVM_1 , B.IMPRVM_2 , B.IMPRVM_3 , B.KEEP_1 , B.KEEP_2 , B.KEEP_3 , B.UNIMPRVM_1 , B.UNIMPRVM_2 , B.UNIMPRVM_3 , B.UNIPT , B.INGRAS ORDER BY A.CMMNS_CD_VALUE ) GROUP BY ROLLUP(CTPV) ORDER BY CTPV_CD
